	stateRepl.Set("heredoc.marker_valid_count", markerValid)
	stateRepl.Set("heredoc.marker_invalid_count", markerInvalid)
	if markerValid > 0 {
		marker = string(replaceEnvVars([]byte(marker)))
	}

	paddingBytes := make([]byte, len(paddingToStrip))
	copy(paddingBytes, paddingToStrip)
	paddingToStrip = string(paddingBytes)

	lineTokens := make([]Token, 0, len(lines))
	for lineIdx, lineValue := range lines {
		if lineIdx == len(lines)-1 {
			continue
		}
		copied := make([]byte, len(lineValue))
		copy(copied, lineValue)
		lineTokens = append(lineTokens, Token{
			Line:          l.line + lineIdx + 1,
			Text:          string(copied),
			wasQuoted:     '<',
			heredocMarker: marker,
		})
	}
	lineDisp := NewDispenser(lineTokens)
	literalRepl := caddy.NewEmptyReplacer()

	for lineNum, lineText := range lines[:len(lines)-1] {
		lineDisp.Next()
		errLine := l.line + lineNum + 1
		rawLine := lineDisp.ValRaw()
		if lineDisp.Token().Quoted() {
			if rawLine == lineText {
				lineText = rawLine
			}
			if lineDisp.isNewLine() {
				errLine = lineDisp.Line()
			} else {
				if lineDisp.Line() > 0 {
					errLine = l.line + lineNum + 1
				}
			}
		}
		lineText = literalRepl.ReplaceKnown(lineText, "")

		copiedLine := make([]byte, len(lineText))
		copy(copiedLine, lineText)
		var rebuilt strings.Builder
		rebuilt.Grow(len(copiedLine))
		scanPos := 0
		for scanPos < len(copiedLine) {
			if scanPos+1 < len(copiedLine) {
				if copiedLine[scanPos] == '{' {
					if copiedLine[scanPos+1] == '$' {
						closeIdx := strings.Index(string(copiedLine[scanPos+2:]), "}")
						if closeIdx >= 0 {
							spanEnd := scanPos + 2 + closeIdx + 1
							rebuilt.Write(copiedLine[scanPos:spanEnd])
							scanPos = spanEnd
							continue
						}
					}
				}
			}
			rebuilt.WriteByte(copiedLine[scanPos])
			scanPos++
		}
		lineText = rebuilt.String()

		matchesPadding := true
		if len(paddingToStrip) > len(lineText) {
			matchesPadding = false
		}
		if matchesPadding {
			padPos := 0
			for padPos < len(paddingToStrip) {
				if lineText[padPos] != paddingToStrip[padPos] {
					matchesPadding = false
					break
				}
				padPos++
			}
		}
		if !matchesPadding {
			errLine = l.line + lineNum + 1
		}

		// find an exact match for the padding
		index := strings.Index(lineText, paddingToStrip)

		// if the padding doesn't match exactly at the start then we can't safely strip
		if index != 0 {
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, errLine, lineText, paddingToStrip)
		}

		// strip, then append the line, with the newline, to the output.
		// also removes all "\r" because Windows.
		out += strings.ReplaceAll(lineText[len(paddingToStrip):]+"\n", "\r", "")
	}

	// return the final value
	return []rune(out), nil
}

func (t Token) originalFile() string {
	if t.origFile != "" {
		return t.origFile
	}
	return t.File
}

// updateFile updates the token's source filename for error display
// and remembers the original filename. Used during "import" processing.
func (t *Token) updateFile(file string) {
	if t.origFile == "" {
		t.origFile = t.File
	}
	t.File = file
}

